const initialBoard = [
    "r", "n", "b", "q", "k", "b", "n", "r",
    "p", "p", "p", "p", "p", "p", "p", "p",
    "", "", "", "", "", "", "", "",
    "", "", "", "", "", "", "", "",
    "", "", "", "", "", "", "", "",
    "", "", "", "", "", "", "", "",
    "P", "P", "P", "P", "P", "P", "P", "P",
    "R", "N", "B", "Q", "K", "B", "N", "R"
];

function Chessboard(id, config) {

    const element = document.getElementById(id);

    let selected = null;
    let enPassantTarget = null;
    let possibleMoves = [];
    let lastMove = { from: null, to: null };

    let boardState = [...initialBoard];

    let currentTurn = "white";

    let gameEnded = false;

    let flipped = PLAYER_COLOR === "black";

    let moved = {
        K: false,
        R1: false,
        R2: false,
        k: false,
        r1: false,
        r2: false
    };

    element.style.display = "grid";
    element.style.gridTemplateColumns = "repeat(8, 1fr)";
    element.style.gridTemplateRows = "repeat(8, 1fr)";
    element.style.width = "400px";
    element.style.height = "400px";

    function render() {

        document.getElementById("turn").innerText =
            "Tur: " + (currentTurn === "white" ? "Vit" : "Svart");

        element.innerHTML = "";

        const displayBoard = flipped
            ? [...boardState].reverse()
            : boardState;

        displayBoard.forEach((piece, displayIndex) => {

            const i = flipped
                ? 63 - displayIndex
                : displayIndex;

            const square = document.createElement("div");

            square.style.width = "100%";
            square.style.height = "100%";

            square.style.display = "flex";
            square.style.alignItems = "center";
            square.style.justifyContent = "center";

            square.style.fontSize = "42px";
            square.style.fontFamily = "Segoe UI Symbol, Arial";
            square.style.lineHeight = "1";
            square.style.cursor = "pointer";

            const pieces = {
                "P": "♙",
                "R": "♖",
                "N": "♘",
                "B": "♗",
                "Q": "♕",
                "K": "♔",
                "p": "♟",
                "r": "♜",
                "n": "♞",
                "b": "♝",
                "q": "♛",
                "k": "♚"
            };

            square.innerText = pieces[piece] || "";

            if (piece !== "") {

                if (piece === piece.toUpperCase()) {

                    square.classList.add("chess-piece-white");

                } else {

                    square.classList.add("chess-piece-black");

                }

            }

            square.addEventListener("click", () => handleClick(i));

            const move = possibleMoves.find(m => m.index === i);

            square.classList.remove(
                "white-square",
                "black-square",
                "selected-square",
                "valid-move",
                "capture-move",
                "last-move"
            );

            if ((Math.floor(displayIndex / 8) + displayIndex) % 2 === 0) {

                square.classList.add("white-square");

            } else {

                square.classList.add("black-square");

            }

            if (i === lastMove.from || i === lastMove.to) {

                square.classList.add("last-move");

            }

            if (i === selected) {

                square.classList.add("selected-square");

            }

            if (move) {

                square.classList.add(
                    move.capture
                        ? "capture-move"
                        : "valid-move"
                );

            }

            element.appendChild(square);

        });
    }

    function isValidMove(from, to) {

        const piece = boardState[from];
        const target = boardState[to];

        const fromRow = Math.floor(from / 8);
        const fromCol = from % 8;

        const toRow = Math.floor(to / 8);
        const toCol = to % 8;

        const dx = toCol - fromCol;
        const dy = toRow - fromRow;

        if (target !== "" && isWhite(piece) === isWhite(target)) {
            return false;
        }

        switch (piece.toLowerCase()) {

            case "p":

                if (isWhite(piece)) {

                    if (dx === 0 && dy === -1 && target === "") return true;

                    if (
                        dx === 0 &&
                        dy === -2 &&
                        fromRow === 6 &&
                        target === "" &&
                        boardState[from - 8] === ""
                    ) return true;

                    if (
                        Math.abs(dx) === 1 &&
                        dy === -1 &&
                        target !== ""
                    ) return true;

                    if (
                        Math.abs(dx) === 1 &&
                        dy === -1 &&
                        target === "" &&
                        to === enPassantTarget
                    ) return true;

                } else {

                    if (dx === 0 && dy === 1 && target === "") return true;

                    if (
                        dx === 0 &&
                        dy === 2 &&
                        fromRow === 1 &&
                        target === "" &&
                        boardState[from + 8] === ""
                    ) return true;

                    if (
                        Math.abs(dx) === 1 &&
                        dy === 1 &&
                        target !== ""
                    ) return true;

                    if (
                        Math.abs(dx) === 1 &&
                        dy === 1 &&
                        target === "" &&
                        to === enPassantTarget
                    ) return true;
                }

                return false;

            case "r":

                if (
                    (dx === 0 || dy === 0) &&
                    isPathClear(from, to)
                ) return true;

                return false;

            case "n":

                if (
                    (Math.abs(dx) === 2 && Math.abs(dy) === 1) ||
                    (Math.abs(dx) === 1 && Math.abs(dy) === 2)
                ) return true;

                return false;

            case "b":

                if (
                    Math.abs(dx) === Math.abs(dy) &&
                    isPathClear(from, to)
                ) return true;

                return false;

            case "q":

                if (
                    (
                        dx === 0 ||
                        dy === 0 ||
                        Math.abs(dx) === Math.abs(dy)
                    ) &&
                    isPathClear(from, to)
                ) return true;

                return false;

            case "k":

                // vit kort rockard
                if (
                    piece === "K" &&
                    from === 60 &&
                    to === 62 &&
                    !moved.K &&
                    !moved.R2 &&
                    boardState[61] === "" &&
                    boardState[62] === "" &&
                    !isKingInCheck("white")
                ) {

                    boardState[61] = "K";
                    boardState[60] = "";

                    if (isKingInCheck("white")) {
                        boardState[60] = "K";
                        boardState[61] = "";
                        return false;
                    }

                    boardState[62] = "K";
                    boardState[61] = "";

                    if (isKingInCheck("white")) {
                        boardState[60] = "K";
                        boardState[62] = "";
                        return false;
                    }

                    boardState[60] = "K";
                    boardState[62] = "";

                    return true;
                }

                // vit lång rockard
                if (
                    piece === "K" &&
                    from === 60 &&
                    to === 58 &&
                    !moved.K &&
                    !moved.R1 &&
                    boardState[59] === "" &&
                    boardState[58] === "" &&
                    boardState[57] === "" &&
                    !isKingInCheck("white")
                ) {

                    boardState[59] = "K";
                    boardState[60] = "";

                    if (isKingInCheck("white")) {
                        boardState[60] = "K";
                        boardState[59] = "";
                        return false;
                    }

                    boardState[58] = "K";
                    boardState[59] = "";

                    if (isKingInCheck("white")) {
                        boardState[60] = "K";
                        boardState[58] = "";
                        return false;
                    }

                    boardState[60] = "K";
                    boardState[58] = "";

                    return true;
                }

                // svart kort rockard
                if (
                    piece === "k" &&
                    from === 4 &&
                    to === 6 &&
                    !moved.k &&
                    !moved.r2 &&
                    boardState[5] === "" &&
                    boardState[6] === "" &&
                    !isKingInCheck("black")
                ) {

                    boardState[5] = "k";
                    boardState[4] = "";

                    if (isKingInCheck("black")) {
                        boardState[4] = "k";
                        boardState[5] = "";
                        return false;
                    }

                    boardState[6] = "k";
                    boardState[5] = "";

                    if (isKingInCheck("black")) {
                        boardState[4] = "k";
                        boardState[6] = "";
                        return false;
                    }

                    boardState[4] = "k";
                    boardState[6] = "";

                    return true;
                }

                // svart lång rockard
                if (
                    piece === "k" &&
                    from === 4 &&
                    to === 2 &&
                    !moved.k &&
                    !moved.r1 &&
                    boardState[3] === "" &&
                    boardState[2] === "" &&
                    boardState[1] === "" &&
                    !isKingInCheck("black")
                ) {

                    boardState[3] = "k";
                    boardState[4] = "";

                    if (isKingInCheck("black")) {
                        boardState[4] = "k";
                        boardState[3] = "";
                        return false;
                    }

                    boardState[2] = "k";
                    boardState[3] = "";

                    if (isKingInCheck("black")) {
                        boardState[4] = "k";
                        boardState[2] = "";
                        return false;
                    }

                    boardState[4] = "k";
                    boardState[2] = "";

                    return true;
                }

                if (
                    Math.abs(dx) <= 1 &&
                    Math.abs(dy) <= 1
                ) return true;

                return false;
        }

        return false;
    }

    function isPathClear(from, to) {

        const fromRow = Math.floor(from / 8);
        const fromCol = from % 8;

        const toRow = Math.floor(to / 8);
        const toCol = to % 8;

        const stepRow = Math.sign(toRow - fromRow);
        const stepCol = Math.sign(toCol - fromCol);

        let row = fromRow + stepRow;
        let col = fromCol + stepCol;

        while (row !== toRow || col !== toCol) {

            const index = row * 8 + col;

            if (boardState[index] !== "") {
                return false;
            }

            row += stepRow;
            col += stepCol;
        }

        return true;
    }

    function findKing(color) {

        const king =
            color === "white"
                ? "K"
                : "k";

        for (let i = 0; i < boardState.length; i++) {

            if (boardState[i] === king) {
                return i;
            }
        }

        return -1;
    }

    function isKingInCheck(color) {

        const kingPos = findKing(color);

        if (kingPos === -1) return false;

        for (let i = 0; i < boardState.length; i++) {

            const piece = boardState[i];

            if (piece === "") continue;

            if (
                color === "white" &&
                piece === piece.toUpperCase()
            ) continue;

            if (
                color === "black" &&
                piece === piece.toLowerCase()
            ) continue;

            if (isValidMove(i, kingPos)) {
                return true;
            }
        }

        return false;
    }

    function hasAnyValidMoves(color) {

        for (let from = 0; from < 64; from++) {

            const piece = boardState[from];

            if (piece === "") continue;

            if (
                color === "white" &&
                piece !== piece.toUpperCase()
            ) continue;

            if (
                color === "black" &&
                piece !== piece.toLowerCase()
            ) continue;

            for (let to = 0; to < 64; to++) {

                if (!isValidMove(from, to)) continue;

                const tempFrom = boardState[from];
                const tempTo = boardState[to];

                boardState[to] = tempFrom;
                boardState[from] = "";

                const inCheck = isKingInCheck(color);

                boardState[from] = tempFrom;
                boardState[to] = tempTo;

                if (!inCheck) {
                    return true;
                }
            }
        }

        return false;
    }

    function getValidMoves(from) {

        let moves = [];

        for (let to = 0; to < 64; to++) {

            if (!isValidMove(from, to)) continue;

            const tempFrom = boardState[from];
            const tempTo = boardState[to];

            const prevEnPassant = enPassantTarget;

            let isCapture = tempTo !== "";

            boardState[to] = tempFrom;
            boardState[from] = "";

            let captured = null;

            if (tempFrom === "P" && to === prevEnPassant) {
                captured = to + 8;
                boardState[captured] = "";
                isCapture = true;
            }

            if (tempFrom === "p" && to === prevEnPassant) {
                captured = to - 8;
                boardState[captured] = "";
                isCapture = true;
            }

            if (!isKingInCheck(currentTurn)) {
                moves.push({
                    index: to,
                    capture: isCapture
                });
            }

            boardState[from] = tempFrom;
            boardState[to] = tempTo;

            if (captured !== null) {
                boardState[captured] =
                    tempFrom === "P"
                        ? "p"
                        : "P";
            }

            enPassantTarget = prevEnPassant;
        }

        return moves;
    }

    function isCheckmate(color) {
        return (
            isKingInCheck(color) &&
            !hasAnyValidMoves(color)
        );
    }

    function handleClick(index) {

        if (gameEnded) return;

        // välj
        if (selected === null) {

            if (boardState[index] === "") return;

            const piece = boardState[index];

            const pieceColor =
                piece === piece.toUpperCase()
                    ? "white"
                    : "black";

            if (pieceColor !== PLAYER_COLOR) {
                return;
            }

            if (currentTurn !== PLAYER_COLOR) {
                return;
            }

            selected = index;

            possibleMoves = getValidMoves(index);

            render();

            return;
        }

        // byt vald pjäs
        const clickedPiece = boardState[index];

        if (
            clickedPiece !== "" &&
            (
                (PLAYER_COLOR === "white" &&
                    clickedPiece === clickedPiece.toUpperCase()) ||

                (PLAYER_COLOR === "black" &&
                    clickedPiece === clickedPiece.toLowerCase())
            )
        ) {

            selected = index;

            possibleMoves = getValidMoves(index);

            render();

            return;
        }

        // ogiltigt drag
        if (!isValidMove(selected, index)) {

            selected = null;
            possibleMoves = [];

            render();

            return;
        }

        const fromIndex = selected;

        const tempFrom = boardState[fromIndex];
        const tempTo = boardState[index];

        const prevEnPassant = enPassantTarget;

        boardState[index] = tempFrom;
        boardState[fromIndex] = "";

        let enPassantCapturedIndex = null;

        if (tempFrom === "P" && index === prevEnPassant) {
            enPassantCapturedIndex = index + 8;
            boardState[enPassantCapturedIndex] = "";
        }

        if (tempFrom === "p" && index === prevEnPassant) {
            enPassantCapturedIndex = index - 8;
            boardState[enPassantCapturedIndex] = "";
        }

        const movedPiece = boardState[index];

        const row = Math.floor(index / 8);

        if (movedPiece === "P" && row === 0) {
            boardState[index] = "Q";
        }

        if (movedPiece === "p" && row === 7) {
            boardState[index] = "q";
        }

        if (isKingInCheck(currentTurn)) {

            boardState[fromIndex] = tempFrom;
            boardState[index] = tempTo;

            if (enPassantCapturedIndex !== null) {
                boardState[enPassantCapturedIndex] =
                    tempFrom === "P"
                        ? "p"
                        : "P";
            }

            selected = null;
            possibleMoves = [];

            render();

            return;
        }

        // en passant 
        if (
            tempFrom.toLowerCase() === "p" &&
            Math.abs(fromIndex - index) === 16
        ) {

            enPassantTarget =
                (fromIndex + index) / 2;

        } else {

            enPassantTarget = null;
        }

        // rockard
        if (tempFrom === "K" && fromIndex === 60 && index === 62) {
            boardState[61] = "R";
            boardState[63] = "";
        }

        if (tempFrom === "K" && fromIndex === 60 && index === 58) {
            boardState[59] = "R";
            boardState[56] = "";
        }

        if (tempFrom === "k" && fromIndex === 4 && index === 6) {
            boardState[5] = "r";
            boardState[7] = "";
        }

        if (tempFrom === "k" && fromIndex === 4 && index === 2) {
            boardState[3] = "r";
            boardState[0] = "";
        }

        if (tempFrom === "K") moved.K = true;
        if (tempFrom === "k") moved.k = true;

        if (tempFrom === "R" && fromIndex === 56) moved.R1 = true;
        if (tempFrom === "R" && fromIndex === 63) moved.R2 = true;

        if (tempFrom === "r" && fromIndex === 0) moved.r1 = true;
        if (tempFrom === "r" && fromIndex === 7) moved.r2 = true;

        lastMove = {
            from: fromIndex,
            to: index
        };

        currentTurn =
            currentTurn === "white"
                ? "black"
                : "white";

        const opponent = currentTurn;

        if (isCheckmate(opponent)) {

            const winner =
                opponent === "white"
                    ? "Svart"
                    : "Vit";

            showGameOver(
                "Matt",
                winner + " vann tyvärr"
            );

            fetch("/SlutprojektWEBB/public/api/finish_game.php", {

                method: "POST",

                headers: {
                    "Content-Type": "application/json"
                },

                body: JSON.stringify({

                    game_id: gameId,

                    result: "finished",

                    winner:
                        winner === "Vit"
                            ? "white"
                            : "black"

                })

            });

        }

        selected = null;
        possibleMoves = [];

        render();

        if (config.onDrop) {
            config.onDrop(boardState);
        }
    }

    render();

    return {

        getGameState: function () {

            return {
                boardState,
                currentTurn,
                moved,
                enPassantTarget,
                lastMove
            };

        },

        isCheckmate: function (color) {

            return isCheckmate(color);

        },

        setGameState: function (state) {

            boardState = state.boardState;
            currentTurn = state.currentTurn;
            moved = state.moved;
            enPassantTarget = state.enPassantTarget;
            lastMove = state.lastMove;

            render();
        },

        flip: function () {

            flipped = !flipped;
            render();

        },

        stopGame: function () {

            gameEnded = true;

        }

    };
}

function isWhite(piece) {
    return piece === piece.toUpperCase();
}